  "commands": [
    {
      "keystrokes": "cat > output.json << 'EOF'
{
  "campaign": {
    "name": "Spring Outreach",
    "marker": "NEAR_BATCH_MARKER_7F3A"
  },
  "near_transfers": {
    "recipients": [
      {
        "account": "alice.near",
